<?php
require_once __DIR__ . '/session_bootstrap.php';
if (empty($_SESSION['username'])) { header('Location: index.php'); exit; }
$devices = json_decode((string)@file_get_contents(__DIR__ . '/config/dvl.json'), true);
if (!is_array($devices)) $devices = array();
$template = json_decode((string)@file_get_contents(__DIR__ . '/config/dashboard_template.json'), true);
if (!is_array($template)) $template = array();
$pointConfig = $template['settings']['chiller_diagram']['floorplan_points'] ?? array();
if (!is_array($pointConfig)) $pointConfig = array();
$remarkConfig = $template['settings']['chiller_diagram']['floorplan_remarks'] ?? array();
if (!is_array($remarkConfig)) $remarkConfig = array();
$layoutConfig = $template['settings']['chiller_diagram']['floorplan_layouts'] ?? array();
if (!is_array($layoutConfig)) $layoutConfig = array();
$planBuilding = strtoupper((string)($_GET['building'] ?? 'MP'));
$planFloor = strtoupper((string)($_GET['floor'] ?? '3'));
if (!preg_match('/^[A-Z0-9]{1,2}$/', $planBuilding)) $planBuilding = 'MP';
if (!preg_match('/^[A-Z0-9]{1,2}$/', $planFloor)) $planFloor = '3';
$planKey = strtolower($planBuilding) . '_floor' . strtolower($planFloor);
$isLegacyMp3 = $planBuilding === 'MP' && $planFloor === '3';
$mpLayout = is_array($layoutConfig[$planKey] ?? null) ? $layoutConfig[$planKey] : array();
$floorplanBackground = (string)($mpLayout['background'] ?? '');
if (!preg_match('#^assets/images/floorplans/[a-z0-9_.-]+\.(?:png|jpe?g|webp)$#i', $floorplanBackground)) $floorplanBackground = $isLegacyMp3 ? 'assets/images/mp-floor3-25d.png' : '';
$mpDevices = array();
foreach ($devices as $serial=>$device) {
    if (preg_match('/^AC' . preg_quote($planBuilding . $planFloor, '/') . '/i', (string)$serial)) $mpDevices[(string)$serial] = (string)($device['name'] ?? $serial);
}
uksort($mpDevices, 'strnatcasecmp');
$canEdit = in_array(strtolower((string)($_SESSION['user_type'] ?? '')), array('admin','superadmin'), true);
