<script>
const planKey=<?php echo json_encode($planKey);?>,planLabel=<?php echo json_encode($planBuilding . ' Floor ' . $planFloor);?>,isLegacyMp3=<?php echo $isLegacyMp3?'true':'false';?>;
const defaultPositions=[[30.9,18.5],[40.5,18.25],[44.65,18.25],[48.55,18.25],[56.75,33.15],[57.05,40.35],[24.8,20.15],[20.8,24.55],[20.8,38.6],[27.55,38.6],[41.3,38.6],[48.2,38.6],[20.8,54.4],[27.35,54.4],[33.65,54.4],[41.3,54.4],[48.2,54.4],[55.95,54.4],[36.45,18.25],[33.65,38.6]],devices=<?php echo json_encode($mpDevices,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>,floorplanPoints=<?php echo json_encode($pointConfig,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>,floorplanRemarks=<?php echo json_encode($remarkConfig,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>,floorplanLayouts=<?php echo json_encode($layoutConfig,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>,templateActive=<?php echo json_encode((string)($template['active']??'chiller_diagram'));?>,templateLabels=<?php echo json_encode($template['labels']??array(),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>,canEdit=<?php echo $canEdit?'true':'false';?>;
const savedLayout=floorplanLayouts[planKey]||{},hasSavedPositions=Array.isArray(savedLayout.positions),savedPositions=hasSavedPositions?savedLayout.positions:[];let positions=(hasSavedPositions?savedPositions:(isLegacyMp3?defaultPositions:[])).filter(pos=>Array.isArray(pos)&&pos.length>=2&&Number.isFinite(Number(pos[0]))&&Number.isFinite(Number(pos[1]))).map(pos=>[Number(pos[0]),Number(pos[1])]),floorplanBackground=savedLayout.background||'<?php echo htmlspecialchars($floorplanBackground,ENT_QUOTES,'UTF-8');?>',layoutEditing=false,layoutSnapshot=null,selectedPointIndex=-1;
const ids=Object.keys(devices),esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),value=(data,keys)=>{for(const key of keys)if(data&&data[key]!==undefined&&data[key]!==null&&data[key]!=='')return data[key];return null};let latestReadings={};
function mapping(){const has=Object.prototype.hasOwnProperty.call(floorplanPoints,planKey),saved=has?(floorplanPoints[planKey]||{}):{},map={};positions.forEach((_,i)=>map['p'+(i+1)]=has?(saved['p'+(i+1)]||''):(ids[i]||''));return map}
function remarks(){return {...(floorplanRemarks[planKey]||{})}}
function render(readings){const scene=document.getElementById('fpScene');scene.querySelectorAll('.fp-pin').forEach(pin=>pin.remove());const map=mapping(),remarkMap=remarks();let assigned=0;positions.forEach((pos,i)=>{const point='p'+(i+1),id=map[point],remark=remarkMap[point]||'',data=readings?.[id],raw=value(data,['temp','temperature']),spRaw=value(data,['sp','setpoint']),temp=Number(raw),sp=Number(spRaw),hasTemp=raw!==null&&Number.isFinite(temp),hasSp=spRaw!==null&&Number.isFinite(sp),online=!!data&&typeof data==='object',running=online&&(Number(data.mode)===2||Number(data.run)===1||Number(data.vs)===1||Number(data.com_1a_status)===1||Number(data.com_2a_status)===1),waiting=running&&hasTemp&&hasSp&&temp>sp,status=!online?'OFFLINE':!running?'STOP':waiting?'RUNNING · ยังไม่ถึง SP':'RUNNING · ถึง SP',stateClass=!id?'is-empty':!online?'is-offline':!running?'is-stop':waiting?'is-waiting':'is-reached',pin=document.createElement('span');pin.className='fp-pin '+stateClass+' is-configurable';pin.style.left=pos[0]+'%';pin.style.top=pos[1]+'%';pin.dataset.temp=hasTemp?temp.toFixed(1)+'°C':'--';pin.title='Point '+String(i+1).padStart(2,'0')+(remark?' · '+remark:'')+(id?' | '+id+' | '+status+' | Temp '+(hasTemp?temp.toFixed(1)+'°C':'--')+' | SP '+(hasSp?sp.toFixed(1)+'°C':'--'):' | ยังไม่กำหนด S/N')+' | คลิกเพื่อดูข้อมูล';pin.tabIndex=0;pin.setAttribute('role','button');pin.setAttribute('aria-label','ดูข้อมูล Point '+String(i+1).padStart(2,'0')+(remark?' '+remark:''));pin.addEventListener('click',()=>openConfig(point));pin.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openConfig(point)}});scene.appendChild(pin);if(id)assigned++});document.getElementById('fpCount').textContent=assigned+' / '+positions.length+' จุด'}
async function refresh(){try{const response=await fetch('api_mdbiotx.php?_='+Date.now(),{cache:'no-store'}),payload=await response.json();if(!response.ok)throw new Error('HTTP '+response.status);latestReadings=payload.data||{};render(latestReadings);document.getElementById('fpUpdated').textContent=payload.dt||new Date().toLocaleTimeString()}catch(error){document.getElementById('fpUpdated').textContent='Connection error'}}
function goBack(){location.href='index.php?page=energy'}
function syncChoices(){}
function detailHtml(point,id){if(!point)return '';const remark=remarks()[point]||'',data=latestReadings?.[id],online=!!data&&typeof data==='object',raw=value(data,['temp','temperature']),spRaw=value(data,['sp','setpoint']),temp=Number(raw),sp=Number(spRaw),hasTemp=raw!==null&&Number.isFinite(temp),hasSp=spRaw!==null&&Number.isFinite(sp),running=online&&(Number(data.mode)===2||Number(data.run)===1||Number(data.vs)===1||Number(data.com_1a_status)===1||Number(data.com_2a_status)===1),waiting=running&&hasTemp&&hasSp&&temp>sp,status=!online?'OFFLINE':!running?'STOP':waiting?'ยังไม่ถึง Setpoint':'ถึง Setpoint',statusClass=!online?'':!running?'stop':waiting?'waiting':'reached',entries=online?Object.entries(data).filter(([key])=>key!=='dt'&&key!=='error'):[];return '<div class="fp-detail-head"><b>'+esc(id||'ยังไม่กำหนด S/N')+'</b><span class="fp-status '+statusClass+'">'+esc(status)+'</span></div>'+(remark?'<div class="fp-detail-remark"><i class="fa-solid fa-note-sticky"></i> '+esc(remark)+'</div>':'')+'<div class="fp-values"><div class="fp-value"><small>Temperature</small><strong>'+(hasTemp?temp.toFixed(1)+'°C':'--')+'</strong></div><div class="fp-value"><small>Setpoint</small><strong>'+(hasSp?sp.toFixed(1)+'°C':'--')+'</strong></div>'+entries.filter(([key])=>!['temp','temperature','sp','setpoint'].includes(key)).map(([key,val])=>'<div class="fp-value" title="'+esc(key)+'"><small>'+esc(key)+'</small><strong>'+esc(val??'--')+'</strong></div>').join('')+'</div>'}
function openConfig(targetPoint=''){const editor=document.getElementById('fpEditor'),modal=document.getElementById('fpModal'),map=mapping(),remarkMap=remarks(),pointList=targetPoint?[targetPoint]:positions.map((_,i)=>'p'+(i+1)),selectedId=targetPoint?(map[targetPoint]||''):'';modal.dataset.targetPoint=targetPoint;document.getElementById('fpConfigTitle').innerHTML='<i class="fa-solid fa-location-dot"></i> '+(targetPoint?'ข้อมูลและ S/N สำหรับ Point '+String(Number(targetPoint.slice(1))).padStart(2,'0')+(remarkMap[targetPoint]?' · '+esc(remarkMap[targetPoint]):''):'กำหนด S/N และ Remark ให้ทุกจุดบนแปลน');document.getElementById('fpPointDetail').innerHTML=detailHtml(targetPoint,selectedId);editor.innerHTML=canEdit?pointList.map(point=>{const i=Number(point.slice(1))-1,selected=map[point]||'',remark=remarkMap[point]||'',options=['<option value="">-- ไม่กำหนด --</option>',...ids.map(id=>'<option value="'+esc(id)+'" '+(id===selected?'selected':'')+'>'+esc(id)+' · '+esc(devices[id])+'</option>')].join('');return '<div class="fp-row '+(targetPoint?'is-target':'')+'" data-point-row="'+point+'"><label>Point '+String(i+1).padStart(2,'0')+'</label><select data-point="'+point+'" onchange="document.getElementById(\'fpPointDetail\').innerHTML=detailHtml(\''+point+'\',this.value)">'+options+'</select><input data-point-remark="'+point+'" maxlength="100" placeholder="Remark ของ Point นี้" value="'+esc(remark)+'"></div>'}).join(''):'';modal.hidden=false;document.body.style.overflow='hidden';if(targetPoint&&canEdit)setTimeout(()=>editor.querySelector('[data-point="'+targetPoint+'"]')?.focus(),50)}
function closeConfig(){document.getElementById('fpModal').hidden=true;document.body.style.overflow=''}
async function saveConfig(button){const targetPoint=document.getElementById('fpModal').dataset.targetPoint||'',map=targetPoint?mapping():{},remarkMap=targetPoint?remarks():{};for(const select of document.querySelectorAll('[data-point]')){if(select.value)map[select.dataset.point]=select.value;else delete map[select.dataset.point]}for(const input of document.querySelectorAll('[data-point-remark]')){const text=input.value.trim();if(text)remarkMap[input.dataset.pointRemark]=text;else delete remarkMap[input.dataset.pointRemark]}const old=button.innerHTML;button.disabled=true;button.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Saving...';try{const plans={...floorplanPoints,[planKey]:map},remarkPlans={...floorplanRemarks,[planKey]:remarkMap},response=await fetch('dashboard_template_api.php?_='+Date.now(),{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:templateActive,labels:templateLabels,settings:{chiller_diagram:{floorplan_points:plans,floorplan_remarks:remarkPlans}}})}),result=await response.json();if(!response.ok||result.status!=='ok')throw new Error(result.message||'Save failed');floorplanPoints[planKey]=map;floorplanRemarks[planKey]=remarkMap;closeConfig();await refresh();await Swal.fire({icon:'success',title:'บันทึก S/N และ Remark แล้ว',timer:1100,showConfirmButton:false})}catch(error){Swal.fire('บันทึกไม่สำเร็จ',error.message,'error')}finally{button.disabled=false;button.innerHTML=old}}
function ensureLayoutButtons(){if(!canEdit||document.getElementById('fpAddPoint'))return;const edit=document.getElementById('fpEditLayout'),upload=document.getElementById('fpUploadBackground'),newPlan=document.createElement('button');newPlan.id='fpNewPlan';newPlan.type='button';newPlan.className='fp-btn warning';newPlan.setAttribute('onclick','startNewFloorplan()');newPlan.innerHTML='<i class="fa-solid fa-file-circle-plus"></i> สร้างแปลนใหม่';upload.insertAdjacentElement('beforebegin',newPlan);upload.onclick=()=>{const input=document.getElementById('fpBackgroundFile');delete input.dataset.newPlan;input.click()};const items=[['fpAddPoint','fa-plus','เพิ่ม Point','addFloorPoint()'],['fpRemovePoint','fa-trash','ลบ Point ที่เลือก','removeFloorPoint()'],['fpResetLayout','fa-rotate-left','คืนค่าเดิม','resetFloorLayout()']];for(const [id,icon,label,action] of items){const button=document.createElement('button');button.id=id;button.type='button';button.className='fp-btn layout-tool';button.hidden=true;button.setAttribute('onclick',action);button.innerHTML='<i class="fa-solid '+icon+'"></i> '+label;edit.insertAdjacentElement('afterend',button)}}
function setLayoutControls(editing){layoutEditing=editing;selectedPointIndex=-1;document.getElementById('fpScene').classList.toggle('is-editing',editing);document.getElementById('fpLayoutHint').hidden=!editing;document.getElementById('fpSaveLayout').hidden=!editing;document.getElementById('fpCancelLayout').hidden=!editing;document.getElementById('fpEditLayout').hidden=editing;document.getElementById('fpNewPlan').hidden=editing;for(const id of ['fpAddPoint','fpRemovePoint','fpResetLayout'])document.getElementById(id).hidden=!editing}
function startNewFloorplan(){if(!canEdit)return;const input=document.getElementById('fpBackgroundFile');input.dataset.newPlan='1';input.click()}
function startLayoutEdit(){if(!canEdit||layoutEditing)return;layoutSnapshot={positions:positions.map(pos=>[...pos]),background:floorplanBackground,points:JSON.parse(JSON.stringify(floorplanPoints[planKey]||{})),remarks:JSON.parse(JSON.stringify(floorplanRemarks[planKey]||{}))};setLayoutControls(true);render(latestReadings)}
function cancelLayoutEdit(){if(!layoutEditing)return;if(layoutSnapshot){positions=layoutSnapshot.positions.map(pos=>[...pos]);floorplanBackground=layoutSnapshot.background;floorplanPoints[planKey]=layoutSnapshot.points;floorplanRemarks[planKey]=layoutSnapshot.remarks;document.getElementById('fpBackground').src=floorplanBackground}layoutSnapshot=null;setLayoutControls(false);render(latestReadings)}
function addFloorPoint(){if(!layoutEditing)return;positions.push([50,50]);selectedPointIndex=positions.length-1;render(latestReadings)}
function removeFloorPoint(){if(!layoutEditing)return;if(selectedPointIndex<0||selectedPointIndex>=positions.length)return Swal.fire('เลือก Point ก่อน','คลิก Point ที่ต้องการลบให้มีกรอบสีเหลือง','info');const removed=selectedPointIndex+1,map=mapping(),remarkMap=remarks(),nextMap={},nextRemarks={};positions.splice(selectedPointIndex,1);for(let number=1;number<=positions.length;number++){const source=number>=removed?number+1:number;if(map['p'+source])nextMap['p'+number]=map['p'+source];if(remarkMap['p'+source])nextRemarks['p'+number]=remarkMap['p'+source]}floorplanPoints[planKey]=nextMap;floorplanRemarks[planKey]=nextRemarks;selectedPointIndex=-1;render(latestReadings)}
async function resetFloorLayout(){if(!layoutEditing)return;const answer=await Swal.fire({icon:'question',title:'คืนค่าแปลนเดิม?',text:isLegacyMp3?'พื้นหลังและตำแหน่ง Point จะกลับเป็นค่าเริ่มต้น 20 จุด':'พื้นหลังและ Point ของชั้นนี้จะถูกล้าง',showCancelButton:true,confirmButtonText:'คืนค่าเดิม',cancelButtonText:'ยกเลิก'});if(!answer.isConfirmed)return;positions=isLegacyMp3?defaultPositions.map(pos=>[...pos]):[];for(const store of [floorplanPoints[planKey]||{},floorplanRemarks[planKey]||{}])for(const key of Object.keys(store))if(Number(key.slice(1))>positions.length)delete store[key];floorplanBackground=isLegacyMp3?'assets/images/mp-floor3-25d.png':'';selectedPointIndex=-1;document.getElementById('fpBackground').src=floorplanBackground;render(latestReadings)}
function attachPinDrag(pin,index){pin.addEventListener('pointerdown',event=>{if(!layoutEditing)return;event.preventDefault();pin.setPointerCapture(event.pointerId);const move=e=>{const rect=document.getElementById('fpScene').getBoundingClientRect(),x=Math.max(0,Math.min(100,(e.clientX-rect.left)/rect.width*100)),y=Math.max(0,Math.min(100,(e.clientY-rect.top)/rect.height*100));positions[index]=[Number(x.toFixed(3)),Number(y.toFixed(3))];pin.style.left=x+'%';pin.style.top=y+'%'};const done=()=>{pin.removeEventListener('pointermove',move);pin.removeEventListener('pointerup',done);pin.removeEventListener('pointercancel',done)};pin.addEventListener('pointermove',move);pin.addEventListener('pointerup',done);pin.addEventListener('pointercancel',done)})}
async function uploadBackground(input){const file=input.files?.[0],creating=input.dataset.newPlan==='1';if(!file)return;if(file.size>10*1024*1024){input.value='';delete input.dataset.newPlan;return Swal.fire('ไฟล์ใหญ่เกินไป','เลือกภาพขนาดไม่เกิน 10 MB','warning')}const body=new FormData();body.append('background',file);body.append('plan_key',planKey);try{const response=await fetch('floorplan_asset_api.php',{method:'POST',credentials:'same-origin',body}),result=await response.json();if(!response.ok||result.status!=='ok')throw new Error(result.message||'Upload failed');if(!layoutEditing)startLayoutEdit();if(creating){positions=[];floorplanPoints[planKey]={};floorplanRemarks[planKey]={};selectedPointIndex=-1}floorplanBackground=result.url;document.getElementById('fpBackground').src=result.url+'?v='+Date.now();render(latestReadings);await Swal.fire({icon:'success',title:creating?'เริ่มแปลนใหม่แล้ว':'เปลี่ยนพื้นหลังแล้ว',text:creating?'กด “เพิ่ม Point” แล้วลากแต่ละจุดไปวางบนแปลน':'ลากจุดให้ตรงตำแหน่ง แล้วกดบันทึกแปลน',timer:2200,showConfirmButton:false})}catch(error){Swal.fire('อัปโหลดไม่สำเร็จ',error.message,'error')}finally{input.value='';delete input.dataset.newPlan}}
async function saveLayout(button){const old=button.innerHTML;button.disabled=true;button.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Saving...';try{const layouts={...floorplanLayouts,[planKey]:{background:floorplanBackground,positions:positions.map(pos=>[Number(pos[0].toFixed(3)),Number(pos[1].toFixed(3))])}},response=await fetch('dashboard_template_api.php?_='+Date.now(),{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:templateActive,labels:templateLabels,settings:{chiller_diagram:{floorplan_layouts:layouts,floorplan_points:floorplanPoints,floorplan_remarks:floorplanRemarks}}})}),result=await response.json();if(!response.ok||result.status!=='ok')throw new Error(result.message||'Save failed');floorplanLayouts[planKey]=layouts[planKey];layoutSnapshot=null;setLayoutControls(false);render(latestReadings);await Swal.fire({icon:'success',title:'บันทึกแปลนแล้ว',timer:1200,showConfirmButton:false})}catch(error){Swal.fire('บันทึกไม่สำเร็จ',error.message,'error')}finally{button.disabled=false;button.innerHTML=old}}
function render(readings){const scene=document.getElementById('fpScene');scene.querySelectorAll('.fp-pin').forEach(pin=>pin.remove());const map=mapping(),remarkMap=remarks();let assigned=0;positions.forEach((pos,i)=>{const point='p'+(i+1),id=map[point],remark=remarkMap[point]||'',data=readings?.[id],raw=value(data,['temp','temperature']),spRaw=value(data,['sp','setpoint']),temp=Number(raw),sp=Number(spRaw),hasTemp=raw!==null&&Number.isFinite(temp),hasSp=spRaw!==null&&Number.isFinite(sp),online=!!data&&typeof data==='object',running=online&&(Number(data.mode)===2||Number(data.run)===1||Number(data.vs)===1||Number(data.com_1a_status)===1||Number(data.com_2a_status)===1),waiting=running&&hasTemp&&hasSp&&temp>sp,status=!online?'OFFLINE':!running?'STOP':waiting?'RUNNING · ยังไม่ถึง SP':'RUNNING · ถึง SP',stateClass=!id?'is-empty':!online?'is-offline':!running?'is-stop':waiting?'is-waiting':'is-reached',pin=document.createElement('span');pin.className='fp-pin '+stateClass+' is-configurable'+(layoutEditing&&selectedPointIndex===i?' is-selected':'');pin.style.left=pos[0]+'%';pin.style.top=pos[1]+'%';pin.dataset.pointNumber=String(i+1).padStart(2,'0');pin.dataset.temp=hasTemp?temp.toFixed(1)+'°C':'--';pin.title='Point '+pin.dataset.pointNumber+(remark?' · '+remark:'')+(id?' | '+id+' | '+status+' | Temp '+(hasTemp?temp.toFixed(1)+'°C':'--')+' | SP '+(hasSp?sp.toFixed(1)+'°C':'--'):' | ยังไม่กำหนด S/N')+(layoutEditing?' | คลิกเลือก หรือลากเพื่อย้าย':' | คลิกเพื่อดูข้อมูล');pin.tabIndex=0;pin.setAttribute('role','button');pin.setAttribute('aria-label','Point '+pin.dataset.pointNumber+(remark?' '+remark:''));pin.addEventListener('click',()=>{if(layoutEditing){selectedPointIndex=i;render(latestReadings)}else openConfig(point)});pin.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();if(layoutEditing){selectedPointIndex=i;render(latestReadings)}else openConfig(point)}});attachPinDrag(pin,i);scene.appendChild(pin);if(id)assigned++});document.getElementById('fpCount').textContent=assigned+' / '+positions.length+' จุด'}
async function refresh(){try{const response=await fetch('api_mdbiotx.php?_='+Date.now(),{cache:'no-store'}),payload=await response.json();if(!response.ok)throw new Error('HTTP '+response.status);latestReadings=payload.data||{};if(!layoutEditing)render(latestReadings);document.getElementById('fpUpdated').textContent=payload.dt||new Date().toLocaleTimeString()}catch(error){document.getElementById('fpUpdated').textContent='Connection error'}}
document.querySelector('.fp-title h1').innerHTML='<i class="fa-solid fa-cube"></i> '+esc(planLabel)+' · Air Conditioner Plan';document.getElementById('fpBackground').alt=planLabel+' floor plan';ensureLayoutButtons();refresh();setInterval(refresh,2000);
</script><script src="assets/js/session-watch.js?v=<?php echo @filemtime(__DIR__ . '/assets/js/session-watch.js'); ?>"></script></body></html>
